const $ = (s) => document.querySelector(s);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => 'Rs ' + Number(n).toLocaleString('en-IN');
const people = [
  {id:'asha',name:'Asha Demo',initials:'AD',title:'Relationship Manager',team:'Client relationships',gross:50000,deductions:3200,login:'09:06',attendance:'Checked in 09:12',color:''},
  {id:'nikhil',name:'Nikhil Demo',initials:'ND',title:'Operations Executive',team:'Operations',gross:45000,deductions:2800,login:null,attendance:'Approved leave',color:'lilac'},
  {id:'riya',name:'Riya Demo',initials:'RD',title:'Relationship Manager',team:'Client relationships',gross:55000,deductions:3500,login:'08:58',attendance:'Check-in missing',color:'sand'}
];
const modules = [
  {id:'payroll',number:'01',title:'Payroll',text:'Salary components, maker-checker review and employee payslips.',screens:['payroll'],video:'01-payroll.mp4',refs:'R135-001 to 005, 018 to 020',question:'Confirm salary components, payroll cutoffs, final approver and historical import scope.'},
  {id:'attendance',number:'02',title:'Attendance & leave',text:'Employee-ID and face-ID check-in, a day-by-day calendar, leave applications and regularization approvals.',screens:['attendance','leave','regularization'],video:'02-attendance-leave.mp4',refs:'R135-006 to 013, 022, 023, 026',question:'Confirm leave types, full/half-day eligibility, working hours, holidays and correction deadlines.'},
  {id:'people',number:'03',title:'Employee hub',text:'Organization structure, login-today indicators, profiles, documents and policies.',screens:['people','profile','policies'],video:'03-employee-hub.mp4',refs:'R135-014 to 017, 025 + latest scope',question:'Confirm document visibility, retention, policy upload rights and who maintains reporting lines.'},
  {id:'whatsapp',number:'04',title:'WhatsApp',text:'Campaigns to clients from mapped templates, scheduled and tracked, the way the team already runs them on InvestWell.',screens:['whatsapp'],video:'04-whatsapp.mp4',refs:'R135-060 to 064',question:'Confirm the business number, which report templates to map first, the sending hours and who may create a campaign.'},
  {id:'performance',number:'05',title:'Performance & appraisals',text:'Explainable scores, salary what-if, peer feedback and a structured review cycle.',screens:['performance','appraisals'],video:'05-performance-appraisals.mp4',refs:'R135-072 to 078',question:'Supply the approved workbook, score weights, peer-feedback rules, salary formula and review chain.'},
  {id:'controls',number:'06',title:'Activity & task controls',text:'Mandatory descriptions and senior-only task edits with reasons and history.',screens:['controls'],video:'06-activity-task-controls.mp4',refs:'R135-040 to 042, 049 + latest scope',question:'Confirm which senior roles may edit and who checks revisions. Processed instructions stay locked.'}
];
const routes={home:'Preview collection',payroll:'Payroll',attendance:'Attendance calendar',leave:'Leave management',regularization:'Regularization',people:'Organization',profile:'Employee profile',policies:'HR policies',whatsapp:'WhatsApp campaigns',performance:'Performance',appraisals:'Appraisals',controls:'Activity & task controls',videos:'Video walkthroughs'};
const state={role:'hr',payroll:'Draft',day:3,month:8,year:2026,leave:[],corrections:[{id:1,date:'2026-09-03',from:'09:15',to:'18:00',reason:'Client visit in the morning; check-in was missed.',status:'Pending'}],checkedIn:false,checkinSource:'Laptop / office',checkinEmp:'',checkinTime:'',wa:{tab:'campaigns',step:0,naming:false,name:'',selected:new Set(),heads:false,excl:{tag:false},search:'',report:'',mode:'later',date:'2026-10-05',time:'10:00',repeat:'Once',when:'',mapIndex:0,campaigns:[{name:'Portfolio valuation, September',report:'Portfolio Valuation',clients:212,when:'01/10/2026 10:00, monthly',status:'Scheduled',delivered:'-'},{name:'Birthday greetings, week 36',report:'Upcoming Birthdays',clients:9,when:'Daily 09:00',status:'Sent',delivered:'9 / 7'},{name:'SIP reminders, September',report:'SIP Upcoming',clients:604,when:'04/09/2026 09:00',status:'Sent',delivered:'596 / 471'}]},profile:'asha',docs:{},ack:{},chat:'open',messages:[],delivery:'Failed: temporary connection',period:'month',scoreRole:'rm',salary:55000,appraisal:'Self-review draft',selfText:'',goalText:'Improve handoff completeness with a weekly checklist review.',managerText:'',activity:[],taskAmount:25000,taskPending:null,taskHistory:[],policyYear:'2026',feedbackStorageError:false};
let route='home',toastTimer,returnFocus;
const avatar=p=>`<span class="avatar ${p.color||''}" aria-hidden="true">${p.initials}</span>`;
const person=p=>`<div class="person">${avatar(p)}<div><strong>${p.name}</strong><small>${p.title}</small></div></div>`;
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const btn=(text,action,primary=false,extra='')=>`<button type="button" ${action?`data-action="${action}"`:''} class="${primary?'primary':''}" ${extra}>${text}</button>`;
const link=(text,r,primary=false)=>`<a class="button ${primary?'primary':''}" href="#${r}">${text}</a>`;
const card=(title,body,sub='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>${body}</section>`;
const stat=(label,value,note='',type='')=>`<div class="card stat ${type}"><span class="stat-label">${label}</span><div class="stat-value">${value}</div><small>${note}</small></div>`;
const notice=(title,text,type='')=>`<div class="notice ${type}"><strong>${title}</strong><p>${text}</p></div>`;
const head=(eyebrow,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const tabs=names=>`<div class="tabs">${names.map(r=>`<a href="#${r}" class="${route===r?'active':''}">${routes[r]}</a>`).join('')}</div>`;
const moneyLine=(label,n,total=false)=>`<div class="line ${total?'total':''}"><span>${label}</span><span class="money">${money(n)}</span></div>`;
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function showToast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function dialog(title,body){returnFocus=document.activeElement;$('#dialog-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();returnFocus?.focus();}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function groupFor(r){return modules.find(m=>m.screens.includes(r)) || {id:'general',title:'Overall preview',question:'Tell us what to keep, change or clarify in the mock screens.'};}
function home(){return head('FOCUSED DESIGN REVIEW','People first. Clearer daily work.','A separate preview for each requested area. Explore the screens, watch the walkthroughs and tell us what needs to change.',link('Watch the walkthroughs','videos',true))+
  `<section class="hero"><div><div class="eyebrow">YOUR NEXT PHASE / SIX FOCUSED PREVIEWS</div><h1>A connected employee experience, ready to review.</h1><p>From attendance and payroll to conversations and performance. Everything here is a working simulation, not a change to the live platform.</p></div><div class="hero-label"><strong>6</strong><span>module walkthroughs</span></div></section>`+
  `<div class="grid cols-3">${modules.map(m=>`<section class="card module-card"><span class="number">${m.number} / PREVIEW</span><h2>${m.title}</h2><p>${m.text}</p><div class="coverage">${m.refs}</div><div class="actions">${link('Explore screens',m.id,true)}${link('Watch video','videos/'+m.id)}</div></section>`).join('')}</div>`+
  notice('Review scope only','NSE order placement, broader dashboards, imports and other tracker work are outside this prototype. Source references remain unchanged. Current mock scope follows your latest instructions.');}
function payroll(){const employee=state.role==='employee',rows=employee?[people[0]]:people;const totalGross=rows.reduce((n,p)=>n+p.gross,0),totalDed=rows.reduce((n,p)=>n+p.deductions,0);return head('HR / MONTHLY PAYROLL',employee?'My payslips':'A calmer payroll close.','August 2026 sample run. Attendance is reconciled before preparation; a separate senior checks the run.',badge(state.payroll,state.payroll==='Finalized'?'':'amber'))+
  `<div class="grid cols-3">${stat(employee?'My gross salary':'Gross salaries',money(totalGross),'Illustrative August data')}${stat('Deductions',money(totalDed),'Example amounts, not statutory rates')}${stat('Net payable',money(totalGross-totalDed),'No bank payment is initiated','accent')}</div>`+
  `<div class="grid split spacer">${card(employee?'My payroll record':'Payroll run / AUG-2026',`<div class="stepper"><div class="done"><strong>01 Prepared</strong>HR manager</div><div class="${state.payroll!=='Draft'?'done':''}"><strong>02 Review</strong>Senior approver</div><div class="${state.payroll==='Finalized'?'done':''}"><strong>03 Finalized</strong>Read-only snapshot</div></div>`+table(['Employee','Gross','Deductions','Net pay','Details'],rows.map(p=>[person(p),money(p.gross),money(p.deductions),`<strong>${money(p.gross-p.deductions)}</strong>`,btn('Breakdown','salary',false,`data-id="${p.id}"`)]))+`<div class="actions spacer">${!employee&&state.role==='hr'&&state.payroll==='Draft'?btn('Submit mock run for review','payroll-submit',true):''}${!employee&&state.role==='senior'&&state.payroll==='In review'?btn('Finalize mock payroll','payroll-finalize',true)+btn('Return for correction','payroll-return'):''}${btn('View sample payslip','payslip')}${state.payroll==='Finalized'?btn('Download sample payslip','payslip-download'):''}</div>`)}
  ${card('Review checklist',`<div class="line"><span>Salary structure</span>${badge('3 reviewed')}</div><div class="line"><span>Attendance reconciliation</span>${badge('August locked')}</div><div class="line"><span>Pending August corrections</span>${badge('None')}</div><div class="line"><span>Prepared by</span><strong>Maya Demo / HR</strong></div><div class="line"><span>Final authority</span><strong>Kiran Demo / Senior</strong></div>`+notice('Two different responsibilities','Switch the preview role above to try the maker and checker. These are simulated UI permissions, not a security implementation.')+`<p class="subtle">Company formulas, tax inputs, cutoff dates, bank export and Zoho history must be confirmed before building the real payroll engine.</p>`)}</div>`;}
function attendanceStatus(day){const date=`${state.year}-${String(state.month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;if(state.leave.some(r=>r.status==='Approved'&&date>=r.from&&date<=r.to))return 'Leave';if(state.month!==8||state.year!==2026)return 'No data';if(day>5)return 'Upcoming';if(state.corrections.some(r=>r.date===date&&r.status==='Approved'))return 'Present';if(state.corrections.some(r=>r.date===date&&r.status==='Pending'))return 'Correction';if(day===4)return 'Leave';if(day===5)return state.checkedIn?'Present':'Not checked in';return 'Present';}
function leaveUsed(type){return state.leave.filter(r=>r.status==='Approved'&&r.type===type).reduce((n,r)=>n+(r.duration==='half'?.5:Math.round((Date.parse(r.to)-Date.parse(r.from))/86400000)+1),0);}
function attendance(){const first=new Date(Date.UTC(state.year,state.month,1)).getUTCDay(),days=new Date(Date.UTC(state.year,state.month+1,0)).getUTCDate();const monthName=new Date(Date.UTC(state.year,state.month,1)).toLocaleString('en',{month:'long',timeZone:'UTC'});const dayState=attendanceStatus(state.day);return head('HR / ATTENDANCE','Every day, in one place.','Review attendance, approved leave and pending corrections without confusing app login with check-in.',btn('Preview check-in','checkin',true))+tabs(['attendance','leave','regularization'])+
  `<div class="grid cols-4">${stat('Employee','Asha Demo','My calendar / sample data')}${stat('Logged in today','09:06','App access only; not attendance')}${stat('Today’s attendance',state.checkedIn?'Present':'Not recorded',state.checkedIn?'Mock check-in recorded':'Check-in still required',state.checkedIn?'accent':'')}${stat('Pending corrections',String(state.corrections.filter(r=>r.status==='Pending').length),'Awaiting senior review','purple')}</div>`+
  `<div class="grid split spacer">${card('Attendance calendar',`<div class="calendar-toolbar">${btn('Previous month','month-prev')}<h2>${monthName} ${state.year}</h2>${btn('Next month','month-next')}</div><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="weekday">${d}</div>`).join('')}${'<div class="day blank"></div>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=i+1,status=attendanceStatus(d),type=status==='Present'?'present':status==='Leave'?'leave':status==='Correction'?'pending':'weekend';return `<button class="day ${d===5&&state.month===8?'today':''} ${d===state.day?'selected':''}" data-action="day" data-id="${d}" aria-label="${d} ${monthName}, ${status}"><strong>${d}</strong><span class="${type}">${status}</span></button>`;}).join('')}</div><div class="legend"><span><i style="background:#92b888"></i>Present</span><span><i style="background:#ada0d0"></i>Approved leave</span><span><i style="background:#dcb862"></i>Correction pending</span><span>No data is not an absence</span></div>`)}
  ${card(`${state.day} ${monthName} / Day details`,`${badge(dayState,dayState==='Correction'?'amber':dayState==='Leave'?'lilac':'')}<div class="spacer"><div class="line"><span>Employee</span><strong>Asha Demo</strong></div><div class="line"><span>Check-in</span><strong>${dayState==='Present'?(state.day===5&&state.checkinTime?esc(state.checkinTime):'09:15'):'Not recorded'}</strong></div><div class="line"><span>Check-out</span><strong>${dayState==='Present'&&state.day<5?'18:00':'Not recorded'}</strong></div><div class="line"><span>Source</span><strong>${dayState==='Present'?(state.day===5?esc(state.checkinSource):'Laptop / office'):'Not available'}</strong></div></div>`+notice('Corrections are not automatic','A pending correction changes the calendar only after approval. Corrections after payroll closes need a controlled adjustment, not a silent rewrite.','amber')+link('Request a correction','regularization',true)+`<p class="subtle spacer">Working hours, lunch treatment, office-network restrictions and field-work exceptions are awaiting your policy.</p>`)}</div>`;}
function leave(){return head('HR / LEAVE','Plan time away, with clarity.','Balances, leave applications and decisions stay connected to the attendance calendar.')+tabs(['attendance','leave','regularization'])+
  `<div class="grid cols-3">${stat('Casual leave',(6-leaveUsed('Casual leave'))+' days','Illustrative balance, not company entitlement','accent')}${stat('Privilege leave',(9-leaveUsed('Privilege leave'))+' days','Half-day availability needs confirmation')}${stat('Requests awaiting review',state.leave.filter(r=>r.status==='Pending').length,'No deduction before approval')}</div><div class="grid cols-2 spacer">${card('Apply for leave',`<form id="leave-form" novalidate><div class="form-grid"><label>Leave type<select name="type"><option>Casual leave</option><option>Privilege leave</option></select></label><label>Duration<select name="duration"><option value="full">Full day</option><option value="half">Half day (policy to confirm)</option></select></label><label>From date<input name="from" type="date" value="2026-09-10"></label><label>To date<input name="to" type="date" value="2026-09-10"></label><label class="full">Reason<textarea name="reason" placeholder="Explain your request"></textarea></label></div><p id="leave-error" class="error" role="alert"></p><button class="primary" type="submit">Submit mock leave request</button></form>`+notice('Policy assumption for review','Casual leave is full-day only in this example. All entitlements, exceptions and special leave categories require written confirmation.','amber'))}${card('My requests',`<div class="request"><div class="actions"><strong>4 September</strong>${badge('Approved','lilac')}</div><p>Privilege leave / 1 day</p><small class="muted">Visible on the attendance calendar.</small></div>${state.leave.map(r=>`<div class="request"><div class="actions"><strong>${esc(r.from)} to ${esc(r.to)}</strong>${badge(r.status,r.status==='Pending'?'amber':'')}</div><p>${esc(r.type)} / ${esc(r.duration)} day<br>${esc(r.reason)}</p>${r.status==='Pending'&&state.role==='senior'?btn('Approve mock leave','leave-approve',true,`data-id="${r.id}"`)+btn('Reject','leave-reject',false,`data-id="${r.id}"`):''}</div>`).join('')}`)}</div>`;}
function regularization(){return head('HR / REGULARIZATION','Correct a record. Keep the history.','A correction is requested by the employee, checked by a senior and then reflected in attendance.')+tabs(['attendance','leave','regularization'])+
  `<div class="grid cols-2">${card('Attendance correction',`<form id="correction-form" novalidate><div class="form-grid"><label class="full">Correction type<select id="correction-kind" name="kind"><option value="attendance">Correct attendance times</option><option value="leave">Convert absence to leave</option></select></label><label id="correction-leave-label" class="full" hidden>Leave type<select name="leaveType"><option>Casual leave</option><option>Privilege leave</option></select></label><label class="full">Date<input name="date" type="date" value="2026-09-02"></label><label>Correct check-in<input name="from" type="time" value="09:15"></label><label>Correct check-out<input name="to" type="time" value="18:00"></label><label class="full">Reason <span aria-hidden="true">*</span><textarea name="reason" placeholder="Explain why the record needs correcting"></textarea></label></div><p id="correction-error" class="error" role="alert"></p><button class="primary">Submit mock correction</button></form>`)}${card('Approval queue',state.corrections.map(r=>`<div class="request"><div class="actions"><strong>${esc(r.date)}</strong>${badge(r.status,r.status==='Pending'?'amber':'')}</div><p>Asha Demo / ${r.kind==='leave'?esc(r.leaveType)+' / full day':r.from+' to '+r.to}<br>${esc(r.reason)}</p><small class="muted">Original record preserved. Reviewer: Kiran Demo.</small><div class="actions">${r.status==='Pending'&&state.role==='senior'?btn('Approve correction','correction-approve',true,`data-id="${r.id}"`)+btn('Reject correction','correction-reject',false,`data-id="${r.id}"`):r.status==='Pending'?'<span class="subtle">Switch to Senior approver to review.</span>':link('View calendar','attendance')}</div></div>`).join('')+notice('Closed payroll is protected','This sample correction belongs to September. It does not rewrite the finalized August run. A later payroll adjustment needs an agreed process.'))}</div>`;}
function organization(){return head('HR / EMPLOYEE HUB','See the team. Find your person.','The organization chart is visible to all employees. App-login indicators are not attendance or live-online indicators.',link('My employee profile','profile',true))+tabs(['people','profile','policies'])+
  `<div class="grid cols-3">${stat('Team members','5','Fictional organization')}${stat('Logged in today','4 of 5','Mock snapshot: 5 Sep, 10:00 IST','accent')}${stat('Reporting structure','3 teams','HR permissions are separate from CRM roles')}</div><section class="card org-tree spacer"><div class="card org-leader">${avatar({initials:'KD',color:'sand'})}<h3>Kiran Demo</h3><p class="subtle">Business head / Senior approver</p><div class="presence"><span class="dot"></span>Logged in today, 08:45</div></div><div class="grid cols-3">${['Client relationships','Operations','People operations'].map((team,i)=>`<section class="org-team"><h3>${team}</h3>${(i===2?[{id:'maya',name:'Maya Demo',initials:'MD',title:'HR Manager',login:'09:00',attendance:'Checked in',color:'lilac'}]:people.filter(p=>p.team===team)).map(p=>`<article class="person-card">${person(p)}<div class="presence ${p.login?'':'off'}"><span class="dot"></span>${p.login?'Logged in today, '+p.login:'Not logged in today'}</div><p class="subtle">${p.id==='maya'?'Reports to Kiran Demo':'Reports to Kiran Demo'}</p>${p.id!=='maya'?`<button class="small-button spacer" data-action="profile" data-id="${p.id}">View profile</button>`:''}</article>`).join('')}</section>`).join('')}</div></section>`+notice('Visible team structure does not mean visible personnel files','Colleagues see work details and login-today status. Salary, résumé, PAN, Aadhaar and private personnel data are limited to self and authorized HR in the proposed design.');}
function profile(){const p=people.find(p=>p.id===state.profile)||people[0],privateAccess=state.role==='hr'||(state.role==='employee'&&p.id==='asha');return head('HR / EMPLOYEE PROFILE','A complete record, carefully shared.','Sample personnel information only. Do not upload real identity documents to this public prototype.')+tabs(['people','profile','policies'])+
  `<section class="card"><div class="profile-top"><span class="avatar large ${p.color}">${p.initials}</span><div><div class="eyebrow">EMPLOYEE / DEMO-${p.id.toUpperCase()}</div><h2>${p.name}</h2><div class="profile-meta"><span>${p.title}</span><span>${p.team}</span><span>Reports to Kiran Demo</span></div></div></div></section><div class="grid cols-2 spacer">${card('Work profile',`<div class="line"><span>Joining date</span><strong>1 April 2025 / sample</strong></div><div class="line"><span>Work location</span><strong>Pune office</strong></div><div class="line"><span>CRM role</span><strong>${p.title}</strong></div><div class="line"><span>HR role</span><strong>Employee self-service</strong></div><div class="line"><span>Logged in today</span><strong>${p.login?`Yes, ${p.login} IST`:'Not yet'}</strong></div>`+notice('Separate signals',`${p.attendance}. A login does not prove a full day of attendance.`))}${card('Personnel documents',privateAccess?['Resume','PAN card','Aadhaar card','Profile photo','Asset handover'].map((name,i)=>`<div class="document"><span class="file-icon">${i===3?'IMG':'PDF'}</span><div class="file-copy"><strong>${name}</strong><small>${state.docs[p.id+name]?'Sample updated / v2':'Fictional placeholder / v1'} · Self + HR only</small></div>${btn('Preview','document',false,`data-id="${esc(name)}"`)}${btn('Use sample','document-update',false,`data-id="${esc(name)}"`)}</div>`).join(''):`<div class="empty"><h3>Personnel files are private</h3><p class="spacer">This preview role can see work details, but not this employee's personnel documents.</p></div>`)}</div>${privateAccess?card('Private profile details',`<div class="grid cols-3"><div><div class="section-label">Personal contact</div><strong>demo@example.invalid</strong><p class="subtle">Phone: not provided in this mock</p></div><div><div class="section-label">Work experience</div><strong>3 years / illustrative</strong><p class="subtle">Previous employment details</p></div><div><div class="section-label">Nominee details</div><strong>Sample nominee</strong><p class="subtle">Relationship and declaration to confirm</p></div></div>`):''}`;}
function policies(){return head('HR / POLICIES','One place for the company handbook.','Current policies and historical versions are available to every employee.',`<label>Policy year<select id="policy-year"><option ${state.policyYear==='2026'?'selected':''}>2026</option><option ${state.policyYear==='2025'?'selected':''}>2025</option></select></label>`)+tabs(['people','profile','policies'])+
  `<div class="grid cols-3">${['Attendance & leave','Employee handbook','Holiday calendar'].map((name,i)=>`<section class="card policy"><span class="file-icon">PDF</span><div>${badge(state.policyYear==='2026'?'Current sample':'Archived sample',state.policyYear==='2025'?'gray':'')}<h2 class="spacer">${name}</h2></div><p>${['Check-in, leave categories and correction process. Company rules still need approval.','Conduct, reporting, work arrangements and employee responsibilities.','A year-specific company holiday list. No statutory calendar is assumed.'][i]}</p><div class="subtle">${state.policyYear} / Version ${state.policyYear==='2026'?'2':'1'} / Fictional policy</div><div class="actions">${btn('Read sample','policy-view',true,`data-id="${name}"`)}${state.ack[name+state.policyYear]?badge('Acknowledged'):btn('Acknowledge sample','policy-ack',false,`data-id="${name}"`)}</div></section>`).join('')}</div>`+notice('Historical versions stay available','Publishing a new policy must not overwrite an old PDF. Acknowledgement is shown as a proposed workflow, not an existing agreed legal acceptance.')+(state.role==='hr'?`<div class="actions spacer">${btn('Preview policy publishing','policy-publish')}</div>`:'');}
const waClients=[['Anil Thombre','Anil Thombre','Asha Demo','ABCPT1234A','98xxxxx182','ETA'],['Meera Kale','Anil Thombre','Asha Demo','ABCPK5678B','98xxxxx410',''],['Vikram Sethi','Vikram Sethi','Rohan Demo','ABCPS9012C','99xxxxx275','NTA'],['Sunita Sethi','Vikram Sethi','Rohan Demo','ABCPS3456D','99xxxxx276',''],['Rajan Iyer','Rajan Iyer','Asha Demo','ABCPI7890E','97xxxxx031','ETA'],['Deepa Nair','Deepa Nair','Kavita Demo','ABCPN2345F','98xxxxx902',''],['Prakash Joshi','Prakash Joshi','Rohan Demo','ABCPJ6789G','96xxxxx118','ETA'],['Neha Joshi','Prakash Joshi','Rohan Demo','ABCPJ0123H','96xxxxx119',''],['Suresh Mhatre','Suresh Mhatre','Kavita Demo','ABCPM4567I','98xxxxx561','NTA'],['Anjali Bhide','Anjali Bhide','Asha Demo','ABCPB8901J','97xxxxx744',''],['Girish Rane','Girish Rane','Kavita Demo','ABCPR2345K','98xxxxx330','ETA'],['Pooja Rane','Girish Rane','Kavita Demo','ABCPR6789L','98xxxxx331','']];
