function waPreview(report){const map={'SIP Upcoming':'Dear Anil Thombre,\n\nThe following SIP instalment is due on 07/10/2026: HDFC Flexi Cap Fund, Rs 10,000. Please keep sufficient balance in your bank account to avoid a failed transaction. Thank you for investing with us.\n\nAcornia Investment Services','Portfolio Valuation':'Dear Anil Thombre,\n\nYour portfolio valuation as on 30/09/2026 is attached. Current value Rs 34,56,000, invested Rs 28,10,000, CAGR 12.4 percent. Reach out to your relationship manager for a review.\n\nAcornia Investment Services','Login Credentials':'Dear Anil Thombre,\n\nYour client portal account is ready. Login: anil.thombre. Set your password using the link: acornia.link/p/8k2f (valid 24 hours).\n\nAcornia Investment Services','Upcoming Birthdays':'Dear Anil Thombre,\n\nWishing you a very happy birthday from all of us at Acornia. May the year ahead bring you health and prosperity.\n\nAsha Demo, Relationship Manager'};return map[report]||'Dear Anil Thombre,\n\n[Message for '+report+' is shown here once the template is mapped.]';}
